def stop_ids(model: Any, processor: Any) -> set[int]:
    result = set()
    for candidate in (model.generation_config.eos_token_id, processor.tokenizer.eos_token_id):
        if candidate is not None:
            result.update(int(i) for i in candidate) if isinstance(candidate, list) else result.add(int(candidate))
    return result
